def divide(a, b):
    if b == 0:
        raise ValueError("除数不能为零")   # raise：主动抛出异常
    return a / b

# try / except / finally
try:
    print(divide(10, 0))
except ValueError as e:
    print("我们接住了异常：", e)          # except：捕获并处理
finally:
    print("无论如何都会执行这一段")        # finally：不管成败都跑

class CountingMeta(type):
    created = 0
    def __new__(mcls, name, bases, namespace):
        mcls.created += 1   # 每造一个类，计数加一
        return super().__new__(mcls, name, bases, namespace)

class A(metaclass=CountingMeta):
    pass

class B(metaclass=CountingMeta):
    pass

print(CountingMeta.created)   # 2，造了 A 和 B 两个类

